  if (sdk.getSkill('Hitpoints').level<=4) {log.push('lowhp');break;}
  const E=cnt(/earth rune/i), W=cnt(/water rune/i), B=cnt(/body rune/i), M=cnt(/mind rune/i), A=cnt(/air rune/i);
  const opts=[];
  if(B>0 && E>=3 && W>=2) opts.push(['CURSE',Spells.CURSE]);
  if(B>0 && E>=2 && W>=3) {opts.push(['WEAKEN',Spells.WEAKEN]); opts.push(['CONFUSE',Spells.CONFUSE]);}
  if(!opts.length && !(M>0&&A>0)){log.push('norunes');break;}
  const ts=sdk.getState().nearbyNpcs.filter(n=>n.optionsWithIndex?.some(o=>/attack/i.test(o.text)) && n.distance<=10).sort((a,b)=>(isC(b)-isC(a))||a.distance-b.distance);
  let pick=null;
  for(const tg of ts){ const o=opts.find(([nm])=>!(used[tg.index]||{})[nm]); if(o){pick=[tg,o[0],o[1]];break;} if(isC(tg) && M>0 && A>0){pick=[tg,'WIND',Spells.WIND_STRIKE];break;} }
  if(!pick){ log.push('no targets'); fails++; await sdk.waitForTicks(3); continue; }
  const [tg,nm,sp]=pick;
  const r = await bot.castSpell(tg, sp, 1500);
  if(nm!=='WIND'){ used[tg.index]=used[tg.index]||{}; used[tg.index][nm]=1; }
  if(r.success) casts++; else {fails++; if(log.length<25) log.push(nm+' '+tg.name+': '+r.message); await bot.dismissBlockingUI();}
}
