const START = Date.parse('2026-11-09T19:21:33.638Z');
const end = START + 30*60000 + 5000;
let lastDropA=-1, lastDropB=-1; const wins={};
const drop = async()=>{ const inv=sdk.getInventory(); if(!inv.length) return; await Promise.all(inv.map(i=>sdk.sendDropItem(i.slot))); await sdk.waitForCondition(s=>s.inventory.length<3, 3000).catch(()=>{}); };
while(Date.now()<end){
  const st = sdk.getState();
  if (st.dialog?.isOpen) { await bot.dismissBlockingUI(); continue; }
  const el = Date.now()-START; const cyc=Math.floor(el/30000); const p = el%30000;
  if (p>=15150 && p<27000 && lastDropA!==cyc && st.inventory.length>3){ lastDropA=cyc; await drop(); continue; }
  if (p>=27900 && lastDropB!==cyc){ lastDropB=cyc; await drop(); continue; }
  if (st.inventory.length>=28){ await drop(); continue; }
  const rock = st.nearbyLocs.filter(l=>/iron ore/i.test(l.name)&&l.distance<3).sort((a,b)=>a.distance-b.distance)[0];
  if(!rock){ await sleep(15); continue; }
  const xp0 = sdk.getSkillXp('Mining');
  await sdk.sendInteractLoc(rock.x, rock.z, rock.id, 1);
  try { await sdk.waitForCondition(s=>{ const m=s.skills.find(k=>k.name==='Mining'); return m.experience>xp0 || !s.nearbyLocs.some(l=>l.x===rock.x&&l.z===rock.z&&l.id===rock.id) || s.dialog?.isOpen; }, 5000);} catch(e){}
  const w=Math.floor((Date.now()-START)/15000); wins[w]=(wins[w]||0)+(sdk.getSkillXp('Mining')-xp0)/875;
}
return [wins];
